/**
 * Differential regression coverage for computed group keys over directional language-tagged literals (RDF 1.2 base
 * direction). Interning a computed value must preserve the literal's base direction: {@code "a"@en--ltr},
 * {@code "a"@en--rtl} and {@code "a"@en} are three distinct RDF terms and must form three distinct groups, with the
 * projected key literals carrying their directions, identically in the native and generic engines.
 */
public class LmdbNativeComputedKeyBaseDirectionTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI label = vf.createIRI(EX, "label");
			conn.add(vf.createIRI(EX, "s1"), label, vf.createLiteral("A", "en", Literal.BaseDirection.LTR));
			conn.add(vf.createIRI(EX, "s2"), label, vf.createLiteral("A", "en", Literal.BaseDirection.RTL));
			conn.add(vf.createIRI(EX, "s3"), label, vf.createLiteral("A", "en"));
		}
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private List<BindingSet> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private static Set<Value> keys(List<BindingSet> rows) {
		return rows.stream().map(row -> row.getValue("k")).collect(Collectors.toSet());
	}

	@Test
	public void computedGroupKeysPreserveBaseDirection() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?k (COUNT(*) AS ?c) WHERE { ?s ex:label ?o . BIND(LCASE(?o) AS ?k) } GROUP BY ?k";

		List<BindingSet> generic = rows(query, false);
		assertThat(generic).as("generic engine must keep the three directional variants apart").hasSize(3);

		List<BindingSet> nativeRows = rows(query, true);
		assertThat(nativeRows).as("native engine must keep the three directional variants apart").hasSize(3);
		assertThat(keys(nativeRows)).as("native computed keys must carry base direction identically to generic")
				.isEqualTo(keys(generic));
	}
}
